void unit_test_swap_basic_swap(void) {
    // Setup: two integers with distinct values
    int x = 5;
    int y = 10;

    // Test: swap the values
    swap(&x, &y);

    // Assertions: values should be swapped
    assert(x == 10);
    assert(y == 5);

    // No dynamic memory to clean up
}
